from threading import Thread
from robot.api import logger

from ute_common_admin import messages
from ute_common_admin.api import AdminApi_v2

from .monitor import InfoModelConnectionMonitor

from six.moves import queue


class InfoModelDataProvider(AdminApi_v2):

    def __init__(self, address, port, username, password, use_ssl, update_interval, debug_log, bundle_path,
                 remote_host, remote_host_username, remote_host_password, timeout, queue_maxsize=0):
        super(InfoModelDataProvider, self).__init__(
            address, port, username, password, use_ssl, update_interval, debug_log, bundle_path,
            remote_host, remote_host_username, remote_host_password, timeout)

        self.listerers = []
        self.connection_monitor = InfoModelConnectionMonitor()

        self.running = False
        self.worker = None
        self.im_request = None
        self.im_msg_queue = queue.Queue(maxsize=queue_maxsize)

    def start(self, timeout):
        """Start InfoModelDataProvider."""
        if self.running and self.worker:
            if self.is_connected():
                logger.warn("InfoModel is already connected.")
                return
            else:
                self.stop()

        self.running = True
        self.worker = Thread(target=self._read_im_updates)
        self.worker.setDaemon(True)
        self.worker.start()

        self.im_request = messages.AdminApiRequest_v2("procedure", "updatesListener", {})
        self._send_message(self.im_request)

        self.connection_monitor.wait_until_connected_to_infomodel(timeout)

    def stop(self):
        """Stop InfoModelDataProvider."""
        if not self.worker:
            return
        try:
            self.execute_procedure("requestsFinalizer", {"requestId": self.im_request.requestId}, timeout=30)
        except Exception as e:
            logger.warn("Cannot finish procedure requestsFinalizer: {} \n{}".format(e, e.__doc__))
        self.running = False
        self.worker.join(2)
        self.worker = None
        with self.im_msg_queue.mutex:
            self.im_msg_queue.queue.clear()
        self.connection_monitor.current_status = self.connection_monitor.OPENED

    def is_connected(self):
        """Check InfoModel connection status."""
        return self.connection_monitor.is_connected_to_infomodel()

    def save_log(self, filename, timeout):
        """Save infomodel log."""
        self.execute_infomodel_request("imsFromCurrentSession", {}, timeout, output_file_name=filename)

    def register_listener(self, listerer):
        """Register listener."""
        self.listerers.append(listerer)

    def unregister_listener(self, listerer):
        """Unregister listener."""
        self.listerers.remove(listerer)

    def _read_im_updates(self):
        while self.running:
            msg = self._get_last_im_response()
            if msg is not None:
                self._handle_message(msg)

    def _get_last_im_response(self):
        try:
            response = self.im_msg_queue.get(block=True, timeout=1)
        except queue.Empty:
            return None
        else:
            return response

    def _handle_message(self, msg):
        payload = msg.get("requestMessage")
        if isinstance(payload, dict):
            self._handle_change_notification(payload)
        elif isinstance(payload, list):
            for item in payload:
                self._handle_change_notification(item)

    def _handle_change_notification(self, notif):
        timestamp = notif.get("timestamp", 0)
        reset = notif.get("reset", False)
        change = notif.get("change", {})

        if reset:
            self._handle_reset(timestamp)

        if change:
            self._handle_objects_update(change.get("updated", []), timestamp)
            self._handle_objects_remove(change.get("removed", []), timestamp)

    def _handle_reset(self, timestamp):
        self.connection_monitor.on_reset()
        for listerer in self.listerers:
            listerer.on_reset(timestamp)

    def _handle_objects_remove(self, removed, timestamp):
        if not removed:
            return
        for listerer in self.listerers:
            listerer.on_remove(removed, timestamp)

    def _handle_objects_update(self, updated, timestamp):
        if not updated:
            return
        updated = {item.get("distName"): item.get("payload") for item in updated if item.get("distName")}
        self.connection_monitor.on_update()
        for listerer in self.listerers:
            listerer.on_update(updated, timestamp)

    def _on_open(self, ws):
        self.msg_queue.put(messages.ConnectionOpen())
        self.connection_monitor.on_open()

    def _on_close(self, ws):
        msg = messages.ConnectionClose()
        self.msg_queue.put(msg)
        self.connection_monitor.on_connection_status_change(msg)

    def _on_error(self, ws, error):
        msg = messages.ConnectionClose(error)
        self.msg_queue.put(msg)
        self.connection_monitor.on_connection_status_change(msg)

    def _on_message(self, ws, payload):
        msg = messages.create_response(payload)
        if isinstance(msg, messages.AdminApiResponse) and self.im_request and msg.match(self.im_request):
            self.im_msg_queue.put(msg)
        else:
            self.msg_queue.put(msg)
